#include <stdio.h>
#include <stdlib.h>

// Функция для чтения матрицы из файла
int** read_matrix(FILE* file, int* rows, int* cols) {
    fscanf(file, "%d %d", rows, cols);
    int** matrix = (int**)malloc(*rows * sizeof(int*));
    if (!matrix) {
        fprintf(stderr, "Ошибка выделения памяти\n");
        exit(1);
    }
    for (int i = 0; i < *rows; i++) {
        matrix[i] = (int*)malloc(*cols * sizeof(int));
        if (!matrix[i]) {
            fprintf(stderr, "Ошибка выделения памяти\n");
            exit(1);
        }
        for (int j = 0; j < *cols; j++) {
            fscanf(file, "%d", &matrix[i][j]);
        }
    }
    return matrix;
}

// Функция для вывода матрицы
void print_matrix(int** matrix, int rows, int cols) {
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            printf("%d", matrix[i][j]);
            if (j < cols - 1) printf(" ");
        }
        printf("\n");
    }
}

// Функция для освобождения памяти матрицы
void free_matrix(int** matrix, int rows) {
    for (int i = 0; i < rows; i++) {
        free(matrix[i]);
    }
    free(matrix);
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Использование: %s <файл_матрицы_A> <файл_матрицы_B>\n", argv[0]);
        return 1;
    }

    FILE* file_a = fopen(argv[1], "r");
    if (!file_a) {
        fprintf(stderr, "Не удалось открыть файл %s\n", argv[1]);
        return 1;
    }

    FILE* file_b = fopen(argv[2], "r");
    if (!file_b) {
        fprintf(stderr, "Не удалось открыть файл %s\n", argv[2]);
        fclose(file_a);
        return 1;
    }

    int rows_a, cols_a;
    int** matrix_a = read_matrix(file_a, &rows_a, &cols_a);
    fclose(file_a);

    int rows_b, cols_b;
    int** matrix_b = read_matrix(file_b, &rows_b, &cols_b);
    fclose(file_b);

    // Проверка размеров (гарантируется одинаковые, но всё же проверим)
    if (rows_a != rows_b || cols_a != cols_b) {
        fprintf(stderr, "Размеры матриц не совпадают\n");
        free_matrix(matrix_a, rows_a);
        free_matrix(matrix_b, rows_b);
        return 1;
    }

    int size = rows_a;

    // Выделение памяти для результатов
    int** sum = (int**)malloc(size * sizeof(int*));
    int** diff = (int**)malloc(size * sizeof(int*));
    int** product = (int**)malloc(size * sizeof(int*));

    for (int i = 0; i < size; i++) {
        sum[i] = (int*)malloc(size * sizeof(int));
        diff[i] = (int*)malloc(size * sizeof(int));
        product[i] = (int*)malloc(size * sizeof(int));
    }

    // Вычисление суммы A + B
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            sum[i][j] = matrix_a[i][j] + matrix_b[i][j];
        }
    }

    // Вычисление разности A - B
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            diff[i][j] = matrix_a[i][j] - matrix_b[i][j];
        }
    }

    // Вычисление произведения A * B
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            product[i][j] = 0;
            for (int k = 0; k < size; k++) {
                product[i][j] += matrix_a[i][k] * matrix_b[k][j];
            }
        }
    }

    // Вывод результатов
    print_matrix(sum, size, size);
    printf("\n");
    print_matrix(diff, size, size);
    printf("\n");
    print_matrix(product, size, size);

    // Освобождение памяти
    free_matrix(matrix_a, rows_a);
    free_matrix(matrix_b, rows_b);
    for (int i = 0; i < size; i++) {
        free(sum[i]);
        free(diff[i]);
        free(product[i]);
    }
    free(sum);
    free(diff);
    free(product);

    return 0;
}

