int main() {
    int n;
    scanf("%d", &n);

    double Y = 0.0;

    for (int i = 0; i < n; i++) {
        double Z, B, A, beta;
        scanf("%lf %lf %lf %lf", &Z, &B, &A, &beta);

        // Вычисляем tg(beta) и проверяем на ноль
        double tan_beta = tan(beta);
        if (fabs(tan_beta) < 1e-10) {
            fprintf(stderr, "Ошибка: тангенс угла beta близок к нулю, деление невозможно.\n");
            return 1;
        }

        double term = Z * Z * Z - B + (A * A) / (tan_beta * tan_beta);
        Y += term;
    }

    printf("%.6f\n", Y);

    return 0;
}

