int main() {
    double x, m;

    // Цикл по x от -1.1 до 0.3 с шагом 0.2
    for (x = -1.1; x <= 0.3; x += 0.2) {
        // Цикл по m от 1 до 5
        for (m = 1.0; m <= 5.0; m++) {
            double power_x = 1.0;
            double power_sin = 1.0;
            double sin_val = sin(x * m);

            // Возводим x в степень m циклом
            for (int i = 0; i < m; i++) {
                power_x *= x;
            }

            // Возводим sin(x*m) в степень m циклом
            for (int i = 0; i < m; i++) {
                power_sin *= sin_val;
            }

            double z = power_x * power_sin;

            printf("%.1f %.0f %.6f\n", x, m, z);
        }
    }

    return 0;
}

