#include <stdio.h>
#include <math.h>

int main() {
    double x, y;

    // Считываем два действительных числа (углы в радианах)
    scanf("%lf %lf", &x, &y);

    // Вычисляем tg(x) = tan(x)
    double tg_x = tan(x);

    // Проверяем, чтобы tg(x) не был равен 1, так как (1 - tg x) в степени ctg x
    // при tg(x) = 1 приводит к делению на ноль или неопределённости
    if (fabs(tg_x - 1.0) < 1e-12) {
        printf("Ошибка: значение выражения не определено при tg(x) = 1\n");
        return 1;
    }

    // Вычисляем ctg(x) = 1 / tan(x)
    double ctg_x = 1.0 / tg_x;

    // Вычисляем (1 - tg x)^(ctg x)
    // Используем pow для возведения в степень
    double power_term = pow(1.0 - tg_x, ctg_x);

    // Вычисляем cos(x - y)
    double cos_term = cos(x - y);

    // Сумма двух слагаемых
    double result = power_term + cos_term;

    // Выводим результат с шестью знаками после запятой
    printf("%.6f\n", result);

    return 0;
}

