#include <stdio.h>

int main() {
    int a, b; // размеры отверстия
    int x, y, z; // габариты кирпича

    // Считываем ввод
    scanf("%d %d", &a, &b);
    scanf("%d %d %d", &x, &y, &z);

    // Отсортируем стороны кирпича по возрастанию, чтобы получить две наименьшие
    int sides[3] = {x, y, z};
    for (int i = 0; i < 2; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (sides[i] > sides[j]) {
                int temp = sides[i];
                sides[i] = sides[j];
                sides[j] = temp;
            }
        }
    }

    // Две наименьшие стороны кирпича
    int min1 = sides[0]; // меньшая сторона
    int min2 = sides[1]; // вторая по малости

    // Проверяем, можно ли пропустить кирпич через отверстие
    // Две наименьшие стороны кирпича должны быть не больше соответствующих сторон отверстия
    if ((min1 <= a && min2 <= b) || (min1 <= b && min2 <= a)) {
        printf("yes\n");
    } else {
        printf("no\n");
    }

    return 0;
}

#include <stdio.h>

int main() {
    unsigned int n;

    // Считываем неотрицательное целое число
    scanf("%u", &n);

    // Если число равно нулю, выводим '0'
    if (n == 0) {
        printf("0");
        return 0;
    }

    // Массив для хранения шестнадцатеричных цифр
    char hex[100];
    int i = 0;

    // Преобразуем число в шестнадцатеричное представление
    while (n > 0) {
        int digit = n % 16;
        if (digit < 10) {
            hex[i] = '0' + digit;
        } else {
            hex[i] = 'A' + (digit - 10);
        }
        i++;
        n /= 16;
    }

    // Выводим результат в обратном порядке
    for (int j = i - 1; j >= 0; j--) {
        printf("%c", hex[j]);
    }

    return 0;
}

#include <stdio.h>
#include <math.h>

int main() {
    double a, b, h;

    // Ввод значений a, b, h
    scanf("%lf %lf %lf", &a, &b, &h);

    // Проверка на корректность отрезка и шага
    if (a <= 0 || b <= 0) {
        printf("Ошибка: x должен быть положительным числом, так как ln(x) определён только для x > 0.\n");
        return 1;
    }

    double x = a;

    // Табулирование функции f(x) = (cos(ln x) / sin(ln x))^2 = ctg^2(ln x)
    while (x <= b + 1e-9) { // Добавляем небольшую поправку для избежания проблем с плавающей точкой
        double ln_x = log(x);

        // Вычисляем sin(ln x) и cos(ln x)
        double sin_ln_x = sin(ln_x);
        double cos_ln_x = cos(ln_x);

        // Проверка на деление на ноль (sin(ln x) == 0)
        if (fabs(sin_ln_x) < 1e-12) {
            printf("%.2lf неопределено\n", x);
        } else {
            double f_x = (cos_ln_x / sin_ln_x) * (cos_ln_x / sin_ln_x);
            printf("%.2lf %.6lf\n", x, f_x);
        }

        x += h;
    }

    return 0;
}

