#include <stdio.h>
#include <math.h>

int main() {
    double a, b, c, d, k;

    // Считываем коэффициенты
    scanf("%lf %lf %lf %lf %lf", &a, &b, &c, &d, &k);

    // Приводим уравнение к виду: a*x^2 + (b - d)*x + (c - k) = 0
    double A = a;
    double B = b - d;
    double C = c - k;

    // Вычисляем дискриминант
    double D = B * B - 4 * A * C;

    // Проверяем количество корней
    if (A == 0) {
        // Уравнение линейное: B*x + C = 0
        if (B == 0) {
            if (C == 0) {
                printf("no roots\n"); // Всё уравнение 0=0 — бесконечно много решений, но по условию "нет корней"
            } else {
                printf("no roots\n");
            }
        } else {
            double x = -C / B;
            printf("%.6f\n", x);
        }
    } else {
        // Квадратное уравнение
        if (D < 0) {
            printf("no roots\n");
        } else if (D == 0) {
            double x = -B / (2 * A);
            printf("%.6f\n", x);
        } else {
            double sqrt_D = sqrt(D);
            double x1 = (-B - sqrt_D) / (2 * A);
            double x2 = (-B + sqrt_D) / (2 * A);

            // Выводим по возрастанию
            if (x1 > x2) {
                double temp = x1;
                x1 = x2;
                x2 = temp;
            }
