int main() {
    char line[1000];
    fgets(line, sizeof(line), stdin);

    int sum = 0;
    int current_number = 0;
    int sign = 1;
    int in_number = 0;

    for (int i = 0; line[i] != '\0'; i++) {
        char c = line[i];

        if (c == ',') {
            sum += current_number * sign;
            current_number = 0;
            sign = 1;
            in_number = 0;
        } else if (c == '-') {
            sign = -1;
            in_number = 1;
        } else if (isdigit(c)) {
            current_number = current_number * 10 + (c - '0');
            in_number = 1;
        }
        // Пропускаем пробелы и другие символы, если нужно
    }

    // Обрабатываем последнее число, если строка не заканчивается запятой
    if (in_number) {
        sum += current_number * sign;
    }

    printf("%d\n", sum);
    return 0;
}

