int main() {
    int n;
    scanf("%d", &n);

    int *arr = (int *)malloc(n * sizeof(int));
    if (!arr) {
        printf("Ошибка выделения памяти\n");
        return 1;
    }

    // Считываем n целых чисел
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    // (1) Номер минимального элемента (нумерация с 1)
    int min_index = 0;
    for (int i = 1; i < n; i++) {
        if (arr[i] < arr[min_index]) {
            min_index = i;
        }
    }
    printf("%d\n", min_index + 1);

    // (2) Произведение элементов между первым и вторым отрицательными элементами
    int first_neg = -1, second_neg = -1;
    for (int i = 0; i < n; i++) {
        if (arr[i] < 0) {
            if (first_neg == -1) {
                first_neg = i;
            } else {
                second_neg = i;
                break;
            }
        }
    }

    long long product = 1;
    int found_two_negatives = 0;

    if (first_neg != -1 && second_neg != -1) {
        found_two_negatives = 1;
        for (int i = first_neg + 1; i < second_neg; i++) {
            product *= arr[i];
        }
    } else {
        product = 0;
    }

    printf("%lld\n", product);

    // (3) Преобразованный массив: сначала элементы, модуль которых не превышает 1,
    // затем все остальные (порядок внутри групп сохраняется)

    int *result = (int *)malloc(n * sizeof(int));
    if (!result) {
        printf("Ошибка выделения памяти\n");
        free(arr);
        return 1;
    }

    int idx = 0;

    // Сначала элементы с |x| <= 1
    for (int i = 0; i < n; i++) {
        if (fabs(arr[i]) <= 1.0) {
            result[idx++] = arr[i];
        }
    }

    // Затем остальные
    for (int i = 0; i < n; i++) {
        if (fabs(arr[i]) > 1.0) {
            result[idx++] = arr[i];
        }
    }

    // Вывод преобразованного массива
    for (int i = 0; i < n; i++) {
        printf("%d ", result[i]);
    }
    printf("\n");

    // Освобождение памяти
    free(arr);
    free(result);

    return 0;
}

