#include <stdio.h>
#include <stdlib.h>

// Функция для вычисления характеристики столбца
int calculate_column_characteristic(int *column, int n) {
    int sum = 0;
    for (int i = 0; i < n; i++) {
        if (column[i] < 0 && column[i] % 2 != 0) {
            sum += abs(column[i]);
        }
    }
    return sum;
}

// Функция для обмена двумя столбцами в матрице
void swap_columns(int **matrix, int n, int col1, int col2) {
    for (int i = 0; i < n; i++) {
        int temp = matrix[i][col1];
        matrix[i][col1] = matrix[i][col2];
        matrix[i][col2] = temp;
    }
}

// Функция для вывода матрицы
void print_matrix(int **matrix, int n, int m) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            printf("%d ", matrix[i][j]);
        }
        printf("\n");
    }
}

int main() {
    int n, m;

    // Ввод размеров матрицы
    scanf("%d %d", &n, &m);

    // Выделение памяти под матрицу
    int **matrix = (int **)malloc(n * sizeof(int *));
    for (int i = 0; i < n; i++) {
        matrix[i] = (int *)malloc(m * sizeof(int));
    }

    // Ввод элементов матрицы
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            scanf("%d", &matrix[i][j]);
        }
    }

    // Массив для хранения характеристик столбцов
    int *characteristics = (int *)malloc(m * sizeof(int));

    // Вычисление характеристик каждого столбца
    for (int j = 0; j < m; j++) {
        int column[m];
        for (int i = 0; i < n; i++) {
            column[i] = matrix[i][j];
        }
        characteristics[j] = calculate_column_characteristic(column, n);
    }

    // Сортировка столбцов по возрастанию характеристик с помощью пузырьковой сортировки
    for (int i = 0; i < m - 1; i++) {
        for (int j = 0; j < m - i - 1; j++) {
            if (characteristics[j] > characteristics[j + 1]) {
                // Обмен столбцов в матрице
                swap_columns(matrix, n, j, j + 1);

                // Обмен характеристик
                int temp = characteristics[j];
                characteristics[j] = characteristics[j + 1];
                characteristics[j + 1] = temp;
            }
        }
    }

    // Вывод результата
    print_matrix(matrix, n, m);

    // Освобождение памяти
    for (int i = 0; i < n; i++) {
        free(matrix[i]);
    }
    free(matrix);
    free(characteristics);

    return 0;
}

