#include <stdio.h>

// Функция для сортировки выбором с подсчётом сравнений
void selectionSort(int arr[], int n, int *comparisons) {
    *comparisons = 0;
    for (int i = 0; i < n - 1; i++) {
        int minIndex = i;
        for (int j = i + 1; j < n; j++) {
            (*comparisons)++;
            if (arr[j] < arr[minIndex]) {
                minIndex = j;
            }
        }
        // Обмен элементов
        if (minIndex != i) {
            int temp = arr[i];
            arr[i] = arr[minIndex];
            arr[minIndex] = temp;
        }
    }
}

// Функция для шейкер-сортировки с подсчётом сравнений
void cocktailSort(int arr[], int n, int *comparisons) {
    *comparisons = 0;
    int left = 0;
    int right = n - 1;

    while (left < right) {
        // Проход слева направо
        for (int i = left; i < right; i++) {
            (*comparisons)++;
            if (arr[i] > arr[i + 1]) {
                int temp = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = temp;
            }
        }
        right--;

        // Проход справа налево
        for (int i = right; i > left; i--) {
            (*comparisons)++;
            if (arr[i - 1] > arr[i]) {
                int temp = arr[i];
                arr[i] = arr[i - 1];
                arr[i - 1] = temp;
            }
        }
        left++;
    }
}

