    int arr[n];
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    // Копируем массив для сортировки выбором
    int selectionArr[n];
    for (int i = 0; i < n; i++) {
        selectionArr[i] = arr[i];
    }

    // Сортируем методом выбора
    int comparisonsSelection = 0;
    selectionSort(selectionArr, n, &comparisonsSelection);

