#include <stdio.h>

// Функция для вычисления определителя матрицы размером n x n с помощью метода Гаусса (приведение к треугольному виду)
double determinant(double matrix[100][100], int n) {
    double det = 1.0;
    double temp;

    // Приводим матрицу к верхней треугольной форме
    for (int i = 0; i < n; i++) {
        // Находим максимальный элемент в столбце i, начиная с строки i
        int max_row = i;
        for (int k = i + 1; k < n; k++) {
            if (matrix[k][i] > matrix[max_row][i]) {
                max_row = k;
            }
        }

        // Если максимальный элемент нулевой, определитель равен 0
        if (matrix[max_row][i] == 0) {
            return 0.0;
        }

        // Меняем строки i и max_row местами
        if (max_row != i) {
            for (int j = 0; j < n; j++) {
                temp = matrix[i][j];
                matrix[i][j] = matrix[max_row][j];
                matrix[max_row][j] = temp;
            }
            det *= -1.0; // Перестановка строк меняет знак определителя
        }

        // Делаем все элементы под диагональю нулевыми
        for (int k = i + 1; k < n; k++) {
            double factor = matrix[k][i] / matrix[i][i];
            for (int j = i; j < n; j++) {
                matrix[k][j] -= factor * matrix[i][j];
            }
        }

        // Умножаем определитель на диагональный элемент
        det *= matrix[i][i];
    }

    return det;
}

int main() {
    int N;
    scanf("%d", &N);

    double matrix[100][100];

    // Считываем матрицу
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            scanf("%lf", &matrix[i][j]);
        }
    }

    // Вычисляем определитель
    double det = determinant(matrix, N);

    // Выводим результат
    printf("%.0f\n", det);

    return 0;
}

#include <stdio.h>

int main() {
    unsigned int x, y;
    int m, n;

    // Считываем входные данные
    scanf("%u %u %d %d", &x, &y, &m, &n);

    // Выводим исходные значения
    printf("%u %u %d %d\n", x, y, m, n);

    // (1) Заменяем младшие m бит числа x на старшие m бит числа y
    if (m > 0) {
        unsigned int mask = ((1U << m) - 1); // маска из m единиц
        unsigned int y_shifted = (y >> (32 - m)) & mask; // берем старшие m бит y и сдвигаем вниз
        x = (x & ~mask) | y_shifted; // заменяем младшие m бит x на y_shifted
    }

    // (2) Инвертируем n младших бит числа y
    if (n > 0) {
        unsigned int mask_n = ((1U << n) - 1); // маска из n единиц
        y ^= mask_n; // инвертируем n младших бит
    }

    // Выводим результат в виде 32-битных двоичных строк
    printf("x = ");
    for (int i = 31; i >= 0; i--) {
        printf("%d", (x >> i) & 1);
    }
    printf("\n");

    printf("y = ");
    for (int i = 31; i >= 0; i--) {
        printf("%d", (y >> i) & 1);
    }
    printf("\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

int main() {
    int N;
    scanf("%d", &N);

    // Если N меньше 2, то простых чисел в интервале [0; N] нет
    if (N < 2) {
        printf("\n");
        return 0;
    }

    // Создаем массив булевых значений для отслеживания простых чисел
    bool *is_prime = (bool *)calloc(N + 1, sizeof(bool));

    // Инициализируем все значения как true (предполагаем, что все числа простые)
    for (int i = 2; i <= N; i++) {
        is_prime[i] = true;
    }

    // Применяем решето Эратосфена
    for (int i = 2; i * i <= N; i++) {
        if (is_prime[i]) {
            // Помечаем все кратные i, начиная с i*i, как составные
            for (int j = i * i; j <= N; j += i) {
                is_prime[j] = false;
            }
        }
    }

    // Выводим простые числа через пробел
    int first = 1;
    for (int i = 2; i <= N; i++) {
        if (is_prime[i]) {
            if (!first) {
                printf(" ");
            }
            printf("%d", i);
            first = 0;
        }
    }

    // Выводим новую строку в конце
    printf("\n");

    // Освобождаем память
    free(is_prime);

    return 0;
}
